116: function jwtChallenge (challenge: Challenge, req: Request, algorithm: string, email: string | RegExp) {
117:   const token = utils.jwtFrom(req)
118:   if (token) {
119:     const decoded = jws.decode(token) ? jwt.decode(token) : null
120: 
121:     if (decoded === null || typeof decoded === 'string') {
122:       return
123:     }
124: 
125:     jwt.verify(token, security.publicKey, (err: jwt.VerifyErrors | null) => {
126:       if (err === null) {
127:         challengeUtils.solveIf(challenge, () => {
128:           return hasAlgorithm(token, algorithm) && hasEmail(decoded as { data: { email: string } }, email)
129:         })
130:       }
131:     })
132:   }
133: }
134: 
135: function hasAlgorithm (token: string, algorithm: string) {
136:   const header = JSON.parse(Buffer.from(token.split('.')[0], 'base64').toString())
137:   return token && header && header.alg === algorithm
138: }
139: 
140: function hasEmail (token: { data: { email: string } }, email: string | RegExp) {
141:   return token?.data?.email?.match(email)
142: }
